package com.example

import com.example.ExamQuestionHelper.QSpec

object DancingLiveExamInstrumentsBank1 {
    private const val T = "පංචතූර්ය නාද වර්ගීකරණය හා නර්තන වාද්‍ය භාණ්ඩ"
    private fun q(stem: String, c: String, d1: String, d2: String, d3: String, exp: String) =
        QSpec(T, stem, c, listOf(d1, d2, d3), exp)

    fun questions(): List<QSpec> = listOf(
        q("ශ්‍රී ලංකාවේ සාම්ප්‍රදායික 'පංචතූර්ය නාද' වර්ගීකරණයට අයත් ප්‍රධාන කොටස් පහ මොනවාද?", "ආතත, විතත, විතතාතත, ඝන සහ සුසිර", "තත්, ස්වර, රාග, තාල සහ ලය", "උඩරට, පහතරට, සබරගමු, භරත සහ කථක්", "දවුල, බෙරය, රබාන, සිතාරය සහ නළාව", "පෙරදිග හා දේශීය වාද්‍ය භාණ්ඩ හඬ උපදවන ආකාරය අනුව මෙම පස් ආකාරයට බෙදා ඇත."),
        q("සම් යොදාගෙන නිපදවා ඇති අතර 'අතින් පමණක්' පහර දී වාදනය කරන වාද්‍ය භාණ්ඩ අයත් වන්නේ කුමන ගණයටද?", "ආතත ගණයට", "විතත ගණයට", "ඝන ගණයට", "සුසිර ගණයට", "ගැටබෙරය, යක් බෙරය, උඩැක්කිය හා රබාන අතින් වයන බැවින් ආතත ගණයට අයත් වේ."),
        q("සම් යොදාගෙන සාදා ඇති අතර 'කෝටුවකින් හෝ කඩිප්පුවකින් පමණක්' ගසා වාදනය කරන භාණ්ඩ ගණය කුමක්ද?", "විතත ගණය", "ආතත ගණය", "සුසිර ගණය", "ඝන ගණය", "තම්මැට්ටම කඩිප්පු යුගලයෙන්ම පමණක් වයන බැවින් එය විතත ගණයට උදාහරණයකි."),
        q("'අතින් සහ කඩිප්පුවෙන්' යන දෙවිධියෙන්ම වාදනය කරනු ලබන සම් බෙර වර්ග අයත් වන ගණය කුමක්ද?", "විතතාතත ගණය", "ආතත ගණය", "ඝන ගණය", "සුසිර ගණය", "දකුණු අතේ කඩිප්පුවෙන්ද වම් අතේ අල්ලෙන්ද වයන දවුල විතතාතත ගණයට අයත් වේ."),
        q("ලෝහ, දැව හෝ පිත්තල වැනි ඝන ද්‍රව්‍ය එකිනෙක ගැටීමෙන් නාද උපදවන වාද්‍ය භාණ්ඩ ගණය කුමක්ද?", "ඝන ගණය", "සුසිර ගණය", "ආතත ගණය", "විතත ගණය", "තාලම්පට, පන්තේරුව, කයිතාලම හා මිණි ගෙඩිය ඝන වාද්‍ය භාණ්ඩ වේ."),
        q("මුවින් සුළං පිඹීමෙන් නාදය නිපදවනු ලබන සිදුරු සහිත වාද්‍ය භාණ්ඩ අයත් වන්නේ කුමන ගණයටද?", "සුසිර ගණයට", "ආතත ගණයට", "විතතාතත ගණයට", "ඝන ගණයට", "හොරණෑව, බටනලාව, හක්ගෙඩිය හා කොම්බුව සුසිර වාද්‍ය භාණ්ඩ ගණයට අයත් වේ."),
        q("නූතන සිංහල සංගීතයේ හා පැරණි කලා වර්ගීකරණයේදී වයලීනය, සිතාරය වැනි තන්තු භාණ්ඩ අයත් වන්නේ කුමන ගණයටද?", "තත හෙවත් තන්තු වාද්‍ය භාණ්ඩ ගණයට", "සුසිර හෙවත් සුළං වාද්‍ය භාණ්ඩ ගණයට", "ඝන හෙවත් ලෝහ වාද්‍ය භාණ්ඩ ගණයට", "ආතත හෙවත් අතින් වයන බෙර ගණයට", "භාරතීය වර්ගීකරණයේ තත, අවනද්ධ, ඝන හා සුසිර ලෙස කොටස් හතරක් දැක්වේ."),
        q("උඩරට සම්ප්‍රදායේ ප්‍රධාන වාද්‍ය භාණ්ඩය වන 'ගැටබෙරයේ' මැද කොටසේ හැඩය කෙබඳු වේද?", "මැදින් පළල් වී දෙකෙළවර සිහින් වූ හැඩයකි", "සෘජු නලයක හැඩයකි", "වැලි හෝරා හැඩයකි", "හතරැස් පෙට්ටියක හැඩයකි", "මැද ගැටයක් වැනි පළල් බවක් ඇති නිසා එයට ගැටබෙරය යන නම ලැබුණි."),
        q("ගැටබෙරයේ බඳ හෙවත් කඳ සකස් කිරීම සඳහා බහුලව යොදාගන්නා ඉතා උචිත දැව වර්ග මොනවාද?", "කොහොඹ, ඇහැල හෝ කොස් දැව", "පැපොල් හා කෙසෙල් කඳන්", "රබර් හා පයිනස්", "උණ බට පමණි", "සවිමත් හා මිහිරි නාදයක් ලබා දෙන කොහොඹ හා ඇහැල දැව ගැටබෙරයට ශ්‍රේෂ්ඨය."),
        q("ගැටබෙරයේ 'දකුණු ඇස' හෙවත් තියුණු නාද ලැබෙන පැත්ත සඳහා යොදන සත්ව සම කුමක්ද?", "රීළවා හෙවත් වඳුරු සම", "ගව සම", "මී හරක් සම", "අලි සම", "තුනී වඳුරු සම නිසා දකුණු අතින් ගසන විට පැහැදිලි ඉහළ ස්වරයක් ලැබේ."),
        q("ගැටබෙරයේ 'වම් ඇස' සකස් කිරීමට යොදන ඝන සත්ව සම කුමක්ද?", "හරක් (ගව) සම", "වඳුරු සම", "තලගොයි සම", "කුකුළු සම", "ඝන හරක් සම නිසා වම් අතින් වැයීමේදී ගැඹුරු බර නාදයක් නිකුත් වේ."),
        q("ගැටබෙරයේ දෙපස ඇස් ඇද තද කර ගැනීමට යොදන දිගු සම් පටිය හඳුන්වන්නේ කෙසේද?", "වරපටිය හෙවත් ගැටබෙර මදු ලණුව", "පන්තේරු රාමුව", "සිළම්බු පටිය", "හොරණෑ පත්‍රය", "ගැටපටි ආධාරයෙන් බෙරයේ හඬ සීරුමාරු කිරීම (ටියුන් කිරීම) සිදු කරයි."),
        q("ගැටබෙරයේ හම් කෙළවර වටා ශක්තිමත්ව අල්ලා ඇති වැල් වළල්ල කුමක්ද?", "වෙණිවැල් වළල්ල හෙවත් කැපුම් වළල්ල", "ලෝහ දම්වැල", "ප්ලාස්ටික් රිං එක", "නූල් බෝලය", "බෙර හම කඳට තද කර ගැනීම සඳහා වෙණිවැල් හෝ වේවැල් වළලු යොදා කුරලය වියයි."),
        q("පහතරට 'යක් බෙරය' ගැටබෙරයෙන් වෙනස් වන ප්‍රධාන ව්‍යුහාත්මක ලක්ෂණය කුමක්ද?", "දෙකෙළවර හා මැද එකම විෂ්කම්භයෙන් යුත් සෘජු සිලින්ඩරාකාර බඳක් තිබීම", "මැද ඉතා පළල් වී දෙකෙළවර උල් වීම", "තනි පැත්තක පමණක් හම තිබීම", "මැටියෙන් තනා තිබීම", "රුහුණු බෙරය දිගු සමාන විෂ්කම්භයක් ඇති නලයක හැඩය ගනී."),
        q("පහතරට යක් බෙරයේ දෙපස ඇස් දෙකම ආවරණය කිරීම සඳහා සාමාන්‍යයෙන් භාවිත කරන සම කුමක්ද?", "ගව ආමාශ පටලය (බොකු සම) හෝ හරක් සම", "වඳුරු සම හෝ තුනී මුව සම පමණි", "රබර් මිශ්‍ර කෘත්‍රිම ප්ලාස්ටික් පටල", "ඝන කඩදාසි හා කපු රෙදි ආවරණ", "එක් කෙළවරකට වඩා දෙපසම තුනී පටල මඟින් විශේෂ අනුනාදී හඬක් යක් බෙරයෙන් ලබා දේ."),
        q("සබරගමු 'දිගු දවුල' වාදනය කිරීමේදී කඩිප්පුව අල්ලා ගනු ලබන්නේ කුමන අතින්ද?", "දකුණු අතින්", "වම් අතින්", "දෙඅතින්ම කඩිප්පු දෙකක්", "පාදයෙන්", "දකුණු අතේ කඩිප්පුවෙන් ගසන අතර වම් අතේ අල්ල හා ඇඟිලිවලින් අනෙක් ඇස වයයි."),
        q("දවුලේ 'කඩිප්පුව' සකස් කර ඇති සාම්ප්‍රදායික අමුද්‍රව්‍යය කුමක්ද?", "වේවැල් හෝ නම්‍යශීලී ලී කැබැල්ලක් රෙදිවලින් ඔතා", "යකඩ පොල්ලක්", "වීදුරු දණ්ඩක්", "ප්ලාස්ටික් බටයක්", "හමට හානි නොවී හොඳ නාදයක් ලබා ගැනීමට කඩිප්පු අග රෙදි ඔතා සකසයි."),
        q("'තම්මැට්ටම' වාද්‍ය භාණ්ඩය නිපදවා ඇත්තේ කුමන ආකාරයකින්ද?", "මැටි හෝ ලී බඳුන් දෙකක් එකට බැඳ මතුපිට හම් ගසා", "තනි ලී කොටයක දෙපස හම් ගසා", "පිත්තල තැටියකින්", "උණ බට පුරුකකින්", "විශාල හා කුඩා ඇස් දෙකකින් යුත් තම්මැට්ටම කඩිප්පු යුගලයකින් වයයි."),
        q("තම්මැට්ටම වාදනය කරන විට හඬෙහි වෙනස ලබා ගන්නා විශාල බඳුන සහ කුඩා බඳුන හඳුන්වන්නේ කෙසේද?", "මන්ද ඇස (බර හඬ) සහ හයිරු ඇස (තියුණු හඬ)", "දකුණු පැත්ත සහ පසුපස", "ඉහළ හා පහළ", "උණුසුම් හා සීතල", "ගව සම් යෙදූ මන්ද ඇසත් එළු සම් හෝ සැහැල්ලු සම් යෙදූ තියුණු ඇසත් එකට බැඳ තිබේ."),
        q("'උඩැක්කිය' වාද්‍ය භාණ්ඩය අයත් වන්නේ පංචතූර්ය වර්ගීකරණයේ කුමන ගණයටද?", "ආතත ගණයට", "විතත ගණයට", "විතතාතත ගණයට", "සුසිර ගණයට", "අතින් හා ඇඟිලිවලින් පමණක් තට්ටු කර වයන බැවින් උඩැක්කිය ආතත ගණයට අයත් වේ."),
        q("උඩැක්කියේ ශබ්දය ස්වර කිහිපයකට වෙනස් කිරීමට (ටියුන් කිරීමට) වාදකයා කරන්නේ කුමක්ද?", "මැද රෙදි පටිය අතින් තද හා බුරුල් කිරීම", "බඳෙහි දෙපස වරපටි අලුතින් ගැට ගැසීම", "කඩිප්පු දෙකකින් දෙපස ඇස්වලට ගැසීම", "බෙර කඳ මත ගිනි අඟුරු තැබීමෙන් රත් කිරීම", "මැද පටිය තද කරන විට හම ඇදී ස්වරය උස් වේ."),
        q("'බුම්මැඩිය' නමැති සාම්ප්‍රදායික බෙරය තනා ඇති මූලික අමුද්‍රව්‍ය මොනවාද?", "පිළිස්සූ මැටි කළයක හැඩැති බඳ සහ තලගොයි හෝ එළු සම", "පිත්තල තහඩුව සහ වඳුරු සම", "උණ බට සහ කපු රෙදි", "කොස් ලීය සහ යකඩ තහඩු", "ගොයම් කවි හා ගැමි නැටුම් සඳහා බුම්මැඩිය ඉතා මිහිරි නාදයක් දෙයි."),
        q("බුම්මැඩිය වාදනය කරනු ලබන්නේ කුමන ශරීර අංගයක් උපයෝගී කර ගනිමින්ද?", "අතින් තට්ටු කිරීමෙන්", "කඩිප්පු දෙකකින් ගැසීමෙන්", "මුවින් පිඹීමෙන්", "පාදයෙන් පෑගීමෙන්", "වම් අතින් උරහිසේ රඳවා දකුණු අතින් බුම්මැඩිය වයන බැවින් එය ආතත භාණ්ඩයකි."),
        q("'බංකු රබාන' වාදනය කිරීමට පෙර රත් කර ගැනීමට ගිනි අඟුරු බඳුනක් යටින් තබන්නේ ඇයි?", "රබානේ සම ඇදී තද වී පැහැදිලි මිහිරි හඬක් ලැබීමට", "රබන් රාමුවේ ලී වර්ණය කළු කිරීමට", "රබන් පද අත්පොත වියළා ගැනීමට", "වටේ සිටින වාදකයන්ට ආලෝකය සැපයීමට", "තෙතමනය ඉවත් වී සම තද වීමෙන් රබන් නාදය ඉතා ප්‍රසන්න වේ."),
        q("'අත් රබාන' සහ 'බංකු රබාන' අතර ඇති ප්‍රධාන වෙනස කුමක්ද?", "අත් රබාන අතින් අල්ලා එක් අයෙකු වයන අතර බංකු රබාන කිහිප දෙනෙකු වට වී වැයීම", "අත් රබාන තඹ හා පිත්තල ලෝහ තැටිවලින් පමණක් සාදා වයන අතර බංකු රබාන කෝටුවලින් වැයීම", "බංකු රබානට කිසිදු සම් පටලයක් නොමැතිව ලී කඳට පමණක් ගසමින් රිද්ම නාදය ලබා ගැනීම", "අත් රබාන සුසිර වාද්‍ය භාණ්ඩයක් සේ මුවින් පිඹින අතර බංකු රබාන තත් ඇද වැයීම", "ප්‍රමාණය හා වාදන ක්‍රමය අනුව මෙම රබන් වර්ග දෙක වෙනස් වේ."),
        q("'හොරණෑව' වාද්‍ය භාණ්ඩය නිර්මාණය කිරීමේදී නාදය උපදවන පිඹින තුඩ සෑදීමට ගන්නා ස්වාභාවික කොළය කුමක්ද?", "තල් කොළ හෙවත් තල් පත්‍ර (පීප්පය)", "කොස් කොළ", "කෙසෙල් කොළ", "තේ කොළ", "පදම් කළ තල් කොළ කැබලි කිහිපයක් බැඳ සාදන පත්‍රය මගින් හොරණෑ නාදය උපදී."),
        q("හොරණෑවේ පහළ කොටසේ ඇති පුළුල් කෝණාකාර කොටස සාදා ඇත්තේ කුමන ලෝහයකින්ද?", "පිත්තල හෝ ලෝකඩ", "වීදුරු", "මැටි", "රබර්", "ලී බඳට සවි කළ පිත්තල පාදම හඬ විශාල කර පිටතට විහිදුවයි."),
        q("පංචතූර්ය වාද්‍ය භාණ්ඩ අතරින් 'හක්ගෙඩිය' අයත් වන්නේ කුමන ගණයටද?", "සුසිර ගණයට", "ආතත ගණයට", "විතත ගණයට", "ඝන ගණයට", "සමුද්‍රික හක්ගෙඩියේ කෙළවර සිදුරු කර මුවින් පිඹින බැවින් සුසිර ගණයට අයත් වේ."),
        q("සම්ප්‍රදායික බෙර හඬ පැහැදිලි බවෙන් තොර නොවී හක්ගෙඩිය පිඹින මංගල අවස්ථාව කුමක්ද?", "පූජාවේ ආරම්භය, දළදා වැඩමවීම හා අවසානය දැන්වීමට", "රාජ සභාවේ විහිළු කෝලම් අවසන් කිරීමට", "නැට්ටුවන්ගේ වෙස් තට්ටුව හිසේ තැබීමට", "ගොයම් නැටුමේ කළගෙඩි බිම තැබීමට", "හක්ගෙඩි නාදය ශුභ නිමිත්තක් හා පූජනීය සංඥාවක් ලෙස සැලකේ."),
        q("'කොම්බුව' නමැති වක්‍ර හැඩැති පිත්තල වාද්‍ය භාණ්ඩය අයත් වන්නේ කුමන වාද්‍ය ගණයටද?", "සුසිර ගණයට", "ආතත ගණයට", "විතතාතත ගණයට", "ඝන ගණයට", "අර්ධ කවාකාර නළාවක් වන කොම්බුව මුවින් පිඹ වාදනය කරනු ලැබේ."),
        q("'තාලම්පට' සාදා ඇත්තේ කුමන ලෝහ මිශ්‍රණයකින්ද?", "පිත්තල හෝ ලෝකඩ (කංස ලෝහය)", "ඇලුමිනියම්", "යකඩ", "ඊයම්", "පැහැදිලි දීප්තිමත් නාදයක් ලැබෙන සේ පිත්තල හා ලෝකඩ මිශ්‍රණයෙන් තාලම්පට නිමවයි."),
        q("තාලම්පට වාදනයේදී නර්තන කණ්ඩායමට එයින් ඉටු වන ප්‍රධානතම සේවය කුමක්ද?", "සම්පූර්ණ නැටුමේ ලය හා තාලය නොවෙනස්ව පාලනය කිරීම", "කවියේ වචන කීම", "නැට්ටුවන්ගේ බර මැනීම", "පසුබිම් ආලෝකය සැපයීම", "බෙර වාදනය අතරතුරදී පවා මූලික තාලය සිහිපත් කිරීම තාලම්පටේ කාර්යයයි."),
        q("'කයිතාලම' නමැති ඝන වාද්‍ය භාණ්ඩය තාලම්පටෙන් වෙනස් වන්නේ කෙසේද?", "තාලම්පටට වඩා විශාල හා පැතලි තැටි දෙකක් වීම", "කයිතාලම මුවින් පිඹින සුසිර භාණ්ඩයක් වීම", "කයිතාලම ශක්තිමත් කොස් ලීයෙන් සාදා තිබීම", "කයිතාලමේ දෙපස තුනී එළු සම ගසා තිබීම", "විශාල හඬක් නඟන කයිතාලම කෝවිල් හා දේවාල පූජාවල බහුලව භාවිත වේ."),
        q("පහතරට හා උඩරට නැටුම්වල පාදවල පළඳින 'සිළම්බු' සහ 'ගෙජ්ජි' අයත් වන්නේ කුමන වාද්‍ය ගණයටද?", "ඝන ගණයට", "සුසිර ගණයට", "ආතත ගණයට", "විතත ගණයට", "ලෝහ ඇට හා කුහර ලෝහ එකිනෙක ගැටීමෙන් ශබ්ද උපදින බැවින් මේවා ඝන භාණ්ඩ වේ."),
        q("'පන්තේරුව' වාද්‍ය භාණ්ඩයක මෙන්ම නර්තන උපකරණයක් ලෙසද හැඳින්වෙන්නේ ඇයි?", "පිත්තල පෙති ගැටීමෙන් රිද්ම නාද උපදවන අතරම නැටුමේ අංගයක් ලෙස කරකවන බැවින්", "එය විශාල බෙරයක් ලෙස බිම ආධාරකයක් මත තබා කඩිප්පු දෙකකින් වාදනය කරන බැවින්", "එයින් උඩරට වන්නම්වල මිහිරි ස්වර තනු හා ගීත සියල්ල ගායනා කළ හැකි බැවින්", "එය හොරණෑවක් මෙන් මුවින් සුළං පිඹ ස්වර සිදුරු වසමින් වාදනය කරන බැවින්", "තාලය හා දෘශ්‍ය හරඹ දෙකම පන්තේරුව මඟින් සිදු වේ."),
        q("'මිණි ගෙඩිය' හෙවත් අත් මිණිය බහුලව භාවිත කරනු ලබන්නේ කුමන කලා අවස්ථාවකදීද?", "බලි යාග, කපු දේව පූජා සහ පන්සල් තේවාවන්හිදී", "කළගෙඩි නැටුමේදී", "ගොයම් නැටුමේදී", "වෙස්මුහුණු කැපීමේදී", "ශාන්තිකර්ම හා පූජාවලදී ශුභ නාදය ඇති කිරීමට අත් මිණිය සොලවනු ලැබේ."),
        q("නර්තන වාද්‍ය භාණ්ඩයක් වන 'ගැටබෙරයේ' සම් ඇද ගැනීමට යොදාගන්නා 'කැපුම' යනු කුමක්ද?", "සම හා කඳ අතර තද කිරීමට බඳින ඝන හම් වළලු", "ගැටබෙර කඳ මැදින් දෙකට කැපීමේ ක්‍රියාවලිය", "බෙර වාදන කඩිප්පු යුගලය සකසා කැපීමේ විධිය", "බෙරය දමන රෙදි උරය කපා මසා ගැනීමේ ක්‍රමය", "කැපුම නිවැරදිව සැකසීමෙන් හම නොබුරුල්ව දිගු කලක් නාදය රඳවා ගනී."),
        q("ශ්‍රී ලාංකේය 'හේවිසි' වාද්‍ය භාණ්ඩ කට්ටලයට අයත් ප්‍රධාන භාණ්ඩ තුන මොනවාද?", "දවුල, තම්මැට්ටම සහ හොරණෑව", "ගැටබෙරය, උඩැක්කිය සහ රබාන", "යක් බෙරය, කළගෙඩිය සහ ලී කෙළි", "තබ්ලාව, සිතාරය සහ බටනලාව", "තේවා හේවිසි, පෙරහැර හේවිසි සහ මළ බෙර හේවිසි සඳහා මෙම කට්ටලය භාවිත වේ."),
        q("බෙර වාදනයේදී බෙර හම තෙතමනයෙන් ආරක්ෂා කර ගැනීමට වාදකයන් අනුගමනය කරන සාම්ප්‍රදායික පිළිවෙත කුමක්ද?", "රෙදි උරයක බහා වියළි ස්ථානයක ආරක්ෂිතව තැබීම", "සෑම වාදනයකටම පසු ජලයෙන් හොඳින් සේදීම", "තෙත් පරිසරයේ විවෘතව රාත්‍රී එළියේ තැබීම", "බෙර කඳ ඇතුළත තෙත් රෙදි කැබලි තබා ගැනීම", "ජලය හෝ තෙතමනය හමට හානි කරන බැවින් ප්‍රවේශමෙන් රැකබලා ගත යුතුය."),
        q("'පණා බෙරය' හෙවත් 'සර්පිණාව' නොවන පැරණි දේශීය හම් බෙර වර්ගයක් කුමක්ද?", "එක් ඇස් බෙරය හෙවත් රබාන / බුම්මැඩිය", "බටහිර වයලීනය", "පියානෝව", "ගිටාරය", "තනි පැත්තක පමණක් හම් ගැසූ දේශීය බෙර කාණ්ඩයට බුම්මැඩිය හා රබන් අයත් වේ."),
        q("වාද්‍ය භාණ්ඩවල 'ලය' හා 'නාද ගුණය' රැකීමට ගැටබෙරයේ වම් ඇස මත තබන 'හබරල' හෝ 'මඩ' තවරන ක්‍රමය දැකිය හැක්කේ කුමන බෙරවලද?", "තබ්ලාව හා මෘදංගයේ මැද කළු මැදීම ලෙස", "තාලම්පටේ ලෝහ තැටි මත ආලේපනයක් ලෙස", "හොරණෑවේ පිත්තල කෝණය මත සැරසිල්ලක් ලෙස", "හක්ගෙඩියේ පිඹින සිදුර වටා වැස්මක් ලෙස", "භාරතීය තබ්ලාවේ හා මෘදංගයේ නාදය පාලනයට මැද කළු පැහැති ස්යාහි ආලේපනය තබයි."),
        q("උඩැක්කි නැටුමේදී උඩැක්කිය වාදනය කරන ශිල්පියා තම ඇඟිලිවලින් පහර දෙන්නේ උඩැක්කියේ කුමන කොටසටද?", "දකුණු පස ඇසට දකුණු අතේ ඇඟිලිවලින්", "මැද රෙදි පටියට කඩිප්පුවෙන්", "දෙපසටම පාදයෙන්", "ලී කෝටු දෙකකින්", "වම් අතින් මැද පටිය අල්ලාගෙන දකුණු අතේ ඇඟිලිවලින් උඩැක්කිය වයනු ලැබේ."),
        q("හොරණෑවේ සිදුරු සංඛ්‍යාව සාමාන්‍යයෙන් කීයක් පමණ වේද?", "ඇඟිලි තැබීම සඳහා සිදුරු හතක් (7) පමණ", "සිදුරු පනහක්", "කිසිදු සිදුරක් නොමැත", "එක් සිදුරක් පමණි", "ඇඟිලිවලින් සිදුරු වැසීමෙන් හා විවෘත කිරීමෙන් විවිධ ස්වර උපදවයි."),
        q("දේශීය නර්තන වාද්‍ය භාණ්ඩවල 'ශුභ නිමිති' හා 'ගෞරවය' පෙන්වීමට වාදකයා වාදනයට පෙර කරන්නේ කුමක්ද?", "බෙරය හිස මත හෝ නළල මත තබා දෑතින් වැඳ නමස්කාර කිරීම", "බෙරය පයින් පෑගීම", "බෙරය බිම දමා පෙරළීම", "වචන කෑගැසීම", "සංගීත උපකරණ දෙවියන් මෙන් සලකා ගෞරව කිරීම පෙරදිග සිරිතයි."),
        q("නර්තන වාද්‍ය භාණ්ඩ අතරින් 'ලී කෙළි' හා 'පොල් කටු' අයත් වන්නේ කුමන තූර්ය ගණයටද?", "ඝන වාද්‍ය ගණයට", "සුසිර වාද්‍ය ගණයට", "විතත වාද්‍ය ගණයට", "ආතත වාද්‍ය ගණයට", "ඝන ද්‍රව්‍ය එකට ගැසීමෙන් තාල නාද උපදින බැවින් ඝන භාණ්ඩ සේ සැලකේ."),
        q("උඩරට ගැටබෙරයේ 'වම් අත' සම හා 'දකුණු අත' සම අතර ඇති ඝනකමේ වෙනස කුමක්ද?", "වම් අතේ හරක් සම ඝන වන අතර දකුණු අතේ වඳුරු සම තුනී වේ", "දෙපසම එකම ඝනකම ඇති ප්ලාස්ටික් වේ", "දකුණු අතේ හරක් සම ඝන වේ", "වම් අතේ වඳුරු සම තුනී වේ", "සමෙහි ඝනකම හා විෂ්කම්භය අනුව තියුණු හා ගැඹුරු නාද දෙකක් උපදී."),
        q("ගැටබෙරයේ දෙපස ඇස් දෙකෙහි විෂ්කම්භය සාමාන්‍යයෙන් පවතින්නේ කෙසේද?", "දකුණු ඇස කුඩා වන අතර වම් ඇස තරමක් විශාල වේ", "දෙපසම හතරැස් වේ", "වම් ඇස කුඩා වී දකුණු ඇස විශාල වේ", "දෙපසම සම් නැත", "කුඩා දකුණු ඇසින් තියුණු හඬත් විශාල වම් ඇසින් බර හඬත් නැඟේ."),
        q("පහතරට 'යක් බෙරය' වාදනය කරන විට වාදකයා බෙරය පිහිටුවා ගන්නේ කෙසේද?", "ඉණෙහි හෝ උරහිසෙහි රඳවාගෙන සෘජුව හෝ මඳක් ඇලව", "බිම තබා පයින් පාගමින්", "හිස මත තබාගෙන", "වතුරේ ගිල්වාගෙන", "දෙඅත් නිදහසේ චලනය කළ හැකි පරිදි ඉණ මට්ටමින් බෙරය රඳවා ගනී."),
        q("දවුලේ 'කඩිප්පුව' සාමාන්‍යයෙන් අල්ලා ගන්නා අත කුමක්ද?", "දකුණු අත", "වම් අත", "දෙපා", "මුව", "දකුණු අතේ කඩිප්පුවෙන් ගසන අතර වම් අතේ අල්ලෙන් විවිධ නාද මවයි."),
        q("තම්මැට්ටම වාදනය කිරීමේදී භාවිත කරන කඩිප්පු දෙකෙහි අග හැඩය කෙබඳු වේද?", "මඳක් වක් වී ඇති අතර ඇතැම් විට රෙදි ඔතා ඇත", "තියුණු ඉඳිකටු හැඩැතිය", "හතරැස් කුට්ටි හැඩැතිය", "පැතලි ලෑලි හැඩැතිය", "වක් වූ අග හේතුවෙන් බෙර සම නොඉරී ප්‍රබල නාදයක් ලබා ගත හැකිය."),
        q("උඩැක්කියේ ඇතුළත සහ පිටත කඳ කොටස තනා ඇති සාම්ප්‍රදායික අමුද්‍රව්‍ය මොනවාද?", "කොස්, ඇහැල හෝ පිත්තල", "ප්ලාස්ටික්", "කාඩ්බෝඩ්", "රබර්", "ලී හෝ ලෝහයෙන් ලියවා අලංකාර වර්ණ ලාක්ෂා වැඩ යොදා උඩැක්කිය නිමවයි."),
        q("උඩැක්කියේ 'දෙපස හම්' එකට සම්බන්ධ කර තබන නූල් පද්ධතිය කුමක්ද?", "කපු ලණු හෙවත් උඩැක්කි මදු ලණු", "යකඩ දම්වැල්", "වයර් කම්බි", "රබර් පටි", "මැද රෙදි පටියෙන් තද කරන විට මෙම ලණු ඇදී හඬ උස් පහත් වේ."),
        q("පංචතූර්ය නාද අතරින් 'සුසිර' ගණයට අයත් හොරණෑවේ ඇඟිලි සිදුරු පිහිටා ඇත්තේ කොතැනද?", "ලී නළාවේ ඉහළ පැත්තේ පේළියට", "පිත්තල කෝණයේ අග", "තල්පත් පීප්පය මත", "බඳෙහි පිටුපස පමණක්", "ඇඟිලිවලින් සිදුරු වැසීමෙන් හා ඇරීමෙන් ස්වර හා ගමක උපදවයි."),
        q("'හක්ගෙඩිය' පිඹින විට එයින් නිකුත් වන්නේ කුමන ආකාරයේ නාදයක්ද?", "ගාම්භීර හා ඈතට ඇසෙන පූජනීය ඒකස්වර නාදයකි", "වේගවත් බෙර පද මාලාවකි", "සිතාර් තන්තු නාදයකි", "තාලම්පට නාදයකි", "දේවාල හා විහාර පූජාවන්හි මංගල ශබ්ද පූජාවක් ලෙස හක්ගෙඩිය පිඹියි."),
        q("'කොම්බුව' නමැති පිත්තල සුසිර වාද්‍ය භාණ්ඩයේ හැඩය සමාන වන්නේ කුමකටද?", "අර්ධ කවාකාර හෝ ඉංග්‍රීසි C අකුරේ හැඩයට", "සෘජු පෙට්ටියකට", "වටකුරු තැටියකට", "ත්‍රිකෝණයකට", "පුරාණයේ සිට රජ පෙරහැර හා දේවාල තේවාවල කොම්බුව භාවිත කර ඇත."),
        q("'තාලම්පට' වාදනය කරන විට වාදකයා තැටි දෙක අල්ලා ගන්නේ කෙසේද?", "පිටුපස නූල් පටියෙන් අල්ලා තැටි දාර නිදහසේ ගැටෙන සේ", "තැටි දෙක තදින් අතින් වසාගෙන", "කඩිප්පු දෙකකින් ගසමින්", "පාදයෙන් පාගාගෙන", "තැටියේ කම්පනයට බාධා නොවන සේ මැද නූලෙන් අල්ලා ගැනීම වැදගත්ය."),
        q("'බුම්මැඩිය' වාදනය කිරීමේදී වාදකයා එය රඳවා තබා ගන්නේ කෙසේද?", "ලණුවකින් උරහිසේ හෝ ඉණෙහි එල්ලා ඇලයට තබාගෙන", "බිම පෙරළාගෙන", "හිස මත තබාගෙන", "දෙපා මැද තබාගෙන", "එක් අතකින් හෝ ලණුවකින් රඳවා දකුණු අතින් මතුපිට හමට තට්ටු කර වයයි."),
        q("නර්තන වාද්‍ය භාණ්ඩ අතර 'බංකු රබාන' සාමාන්‍යයෙන් වාදනය කරනු ලබන්නේ කවුරුන් විසින්ද?", "කිහිප දෙනෙකු වට වී අත් දෙකෙන්ම රබන් පද වයමින්", "තනි පුද්ගලයෙකු මුවින් පිඹිමින්", "කඩිප්පු යුගලයකින් ගසමින්", "වේදිකාවෙන් පිටත සිට", "සිංහල අලුත් අවුරුදු සමයේ කාන්තාවන් රබාන වටා සිට රබන් පද වයති."),
        q("'පන්තේරුව' වාද්‍ය භාණ්ඩයේ පිත්තල රාමුවේ සවි කර ඇති කුඩා තැටි යුගල හඳුන්වන්නේ කුමන නමකින්ද?", "ජලංගි හෙවත් පිත්තල පෙති (සිලිං)", "වරපටි", "කුරල", "මදු ලණු", "රාමුවේ කපන ලද සිදුරු තුළ කුඩා ඇණ මත මෙම ලෝහ පෙති නිදහසේ චලනය වේ."),
        q("'මිණි ගෙඩිය' (අත් මිණිය) වාදනයේදී හඬ නිකුත් වන්නේ කෙසේද?", "මැද ඇති ලෝහ දිව ඇතුළත ලෝහ බඳේ ගැටීමෙන්", "මුවින් පිඹීමෙන්", "කඩිප්පුවෙන් ගැසීමෙන්", "තත් සෙලවීමෙන්", "ඝන වාද්‍ය භාණ්ඩයක් වන මිණි ගෙඩිය පූජා විධිවලදී බහුලව යොදයි."),
        q("පංචතූර්ය නාද වර්ගීකරණයේදී 'ආතත, විතත, විතතාතත' යන තුනටම පොදුවේ ගැනෙන අනෙක් නම කුමක්ද?", "අවනද්ධ (සම් යෙදූ) වාද්‍ය භාණ්ඩ", "සුසිර වාද්‍ය භාණ්ඩ", "ඝන වාද්‍ය භාණ්ඩ", "තත වාද්‍ය භාණ්ඩ", "බෙර වර්ග සියල්ලම සමකින් වැසී ඇති බැවින් අවනද්ධ නමින් හැඳින්වේ."),
        q("ශ්‍රී ලංකාවේ දළදා මාලිගාවේ තේවාව සඳහා යොදාගන්නා ප්‍රධාන වාද්‍ය භාණ්ඩ කට්ටලය කුමක්ද?", "දවුල, තම්මැට්ටම, හොරණෑව සහ හක්ගෙඩිය (හේවිසි කට්ටලය)", "තබ්ලාව, සිතාරය සහ බටනලාව", "වයලීනය සහ පියානෝව", "ලී කෙළි සහ කළගෙඩි", "තේවා හේවිසි පූජාව ලංකාවේ පැරණිතම අඛණ්ඩ සංගීත පූජාවකි."),
        q("ගැටබෙරයේ 'වරපටි' ඇද තද කිරීමෙන් පසු බෙර හම සමබරව සකසා ගැනීම හඳුන්වන්නේ කෙසේද?", "බෙරය හඬ ගැළපීම හෙවත් මට්ටම් කිරීම (Tuning)", "බෙරය කැඩීම", "බෙරය වතුරේ දැමීම", "සම ඉවත් කිරීම", "දකුණු ඇස සහ වම් ඇස අතර නිවැරදි නාද සමබරතාව පවත්වා ගැනීම වැදගත් වේ."),
        q("පහතරට 'යක් බෙරය' වාදනයේදී වාදකයා වේගවත් කොටස් වැයීමේදී භාවිත කරන ප්‍රධාන ශිල්පීය ක්‍රමය කුමක්ද?", "ඇඟිලි තුඩු සහ අත්ල මාරු කරමින් ප්‍රබල අත් හුරුව දැක්වීම", "කඩිප්පු දෙකක් භාවිත කිරීම", "බෙරය බිම තැබීම", "මුවින් පිඹීම", "පහතරට බෙර වාදකයාගේ වේගවත් ඇඟිලි චලන අතිශය ආකර්ෂණීය වේ."),
        q("'දිගු දවුල' හා 'ගැටබෙරය' අතර ප්‍රමාණයෙන් හා හැඩයෙන් දැකිය හැකි ප්‍රධාන වෙනස කුමක්ද?", "දවුල සිලින්ඩරාකාර විශාල කඳකින් යුක්ත වන අතර ගැටබෙරය මැදින් පළල් වේ", "ගැටබෙරය විශාල වන අතර දවුල කුඩා වේ", "දෙකම පිත්තලවලින් සාදා ඇත", "දෙකටම සම් නැත", "සබරගමු දිගු දවුල ප්‍රමාණයෙන් ඉතා විශාල ගැඹුරු හඬක් දෙන බෙරයකි."),
        q("තම්මැට්ටමේ 'හයිරු ඇස' (තියුණු හඬ ඇති බඳුන) සඳහා සාමාන්‍යයෙන් යොදන සම කුමක්ද?", "එළු සම හෝ තුනී ගව සම", "අලි සම", "මී හරක් ඝන සම", "ප්ලාස්ටික් පටල", "කුඩා ඇසට තුනී සම යෙදීමෙන් පැහැදිලි තියුණු හඬක් ලැබේ."),
        q("'සිළම්බු' නමැති පාද ආභරණය හා වාද්‍ය භාණ්ඩය නිර්මාණය කරන්නේ කුමන ලෝහයකින්ද?", "පිත්තල හෝ ලෝකඩ", "ඊයම්", "යකඩ පමණක්", "ඇලුමිනියම්", "නැට්ටුවාගේ සෑම පාද පියවරකටම අලංකාර රිද්ම හඬක් සිළම්බුවලින් ලැබේ."),
        q("උඩරට 'ගෙජ්ජි වැල්' පාදවල බඳින විට ඒවා සකස් කරන්නේ කුමන ද්‍රව්‍යයක් මතද?", "ශක්තිමත් සම් හෝ රෙදි පටියක් මත කුඩා ලෝහ ගෙජ්ජි අමුණා", "යකඩ දම්වැලක් මත", "ප්ලාස්ටික් පටියක් මත", "කෙසෙල් පතුරක් මත", "පාදයට හානි නොවන සේ මෘදු රෙදි හෝ සම් පටිවල ගෙජ්ජි අමුණා බඳියි."),
        q("හොරණෑවේ 'තල්පත් පීප්පය' වියළී තිබෙන විට වාදනයට පෙර වාදකයා කරන්නේ කුමක්ද?", "ජලයෙන් මඳක් තෙත් කර නම්‍යශීලී කර ගැනීම", "ගින්නෙන් පුළුස්සා දැමීම", "තෙල් ගෑම", "කඩිප්පුවෙන් ගැසීම", "තල් කොළය මෘදු වූ විට පමණක් පිඹීමෙන් පැහැදිලි හා මිහිරි නාදයක් ලැබේ."),
        q("'කයිතාලම' වාදනය කිරීමේදී වාදකයා අනුගමනය කරන ආකාරය කුමක්ද?", "තැටි දෙකම දෙඅතින් අල්ලා එකට ගැසීම", "එක් තැටියක් බිම තබා පෑගීම", "මුවින් පිඹීම", "කඩිප්පුවෙන් ගැසීම", "විශාල පිත්තල තැටි දෙකේ හඬ දේවාල උත්සවවල ඉතා ජනප්‍රිය වේ."),
        q("පංචතූර්ය නාද වර්ගීකරණයේදී 'බටනලාව' අයත් වන්නේ කුමන ගණයටද?", "සුසිර ගණයට", "ඝන ගණයට", "ආතත ගණයට", "විතත ගණයට", "සිදුරු තුළින් වායු කඳ කම්පනය වීමෙන් හඬ නැඟෙන බැවින් සුසිර ගණයට වැටේ."),
        q("ශ්‍රී ලංකාවේ පැරණි ගැමි ජන නැටුම්වල 'තාල භාණ්ඩයක්' ලෙස භාවිත කළ 'කළගෙඩිය' හඬ නඟන්නේ කෙසේද?", "කටට මුව තබා පිඹීමෙන් සහ බඳට අතින් තට්ටු කිරීමෙන්", "පොළොවේ ගසා බිඳීමෙන්", "ලී කෝටුවලින් ගැසීමෙන්", "වතුර පුරවා විසි කිරීමෙන්", "මැටි කළය සරල සුසිර හා තාල භාණ්ඩයක් ලෙස යොදාගෙන ඇත."),
        q("ගැටබෙරයේ 'මුහුණත' (ඇස) ආරක්ෂා කර ගැනීමට වාදනය නොකරන විට කරන්නේ කුමක්ද?", "රෙදි හෝ හම් වැස්මකින් (බෙර උරයකින්) වසා තැබීම", "තද අව්වේ තැබීම", "ජලය ඉසීම", "බර ද්‍රව්‍ය උඩින් තැබීම", "දූවිලි හා තෙතමනයෙන් ආරක්ෂා කිරීමට බෙර ආවරණ භාවිත කෙරේ."),
        q("නර්තන වාද්‍ය භාණ්ඩ අතර 'විතතාතත' ගණයට අයත් භාණ්ඩයක් තෝරන්න.", "දවුල", "තම්මැට්ටම", "ගැටබෙරය", "තාලම්පට", "අතින් හා කඩිප්පුවෙන් යන දෙවිධියෙන්ම වයන බැවින් දවුල මෙම ගණයට අයත් වේ."),
        q("නර්තන වාද්‍ය භාණ්ඩ අතර 'විතත' ගණයට අයත් භාණ්ඩය තෝරන්න.", "තම්මැට්ටම", "උඩැක්කිය", "යක් බෙරය", "හොරණෑව", "කඩිප්පු දෙකකින් පමණක් ගසා වාදනය කරන භාණ්ඩ විතත ගණයට වැටේ."),
        q("නර්තන වාද්‍ය භාණ්ඩ අතර 'ආතත' ගණයට අයත් නොවන භාණ්ඩය කුමක්ද?", "තම්මැට්ටම", "ගැටබෙරය", "යක් බෙරය", "උඩැක්කිය", "තම්මැට්ටම වයන්නේ අතින් නොව කඩිප්පු යුගලයකිනි."),
        q("ශ්‍රී ලාංකේය සාම්ප්‍රදායික බෙර කඳන් කැටයම් කිරීමේදී මැද කොටසේ සිදුරු කරන ප්‍රමාණය බලපාන්නේ කුමකටද?", "බෙරයේ නාද ගැඹුර, දෝංකාරය සහ බරට", "බෙරයේ පැහැයට පමණක්", "කඩිප්පුවේ දිගට", "වරපටියේ වර්ගයට", "ලී කඳෙහි ඇතුළත හැඩය අනුනාද ගුණාත්මක බව තීරණය කරයි."),
        q("'මඟුල් බෙර' වාදනය කිරීමේදී වාදකයා සාමාන්‍යයෙන් පළඳින සාම්ප්‍රදායික ඇඳුම කුමක්ද?", "සුදු රෙද්ද හෝ නිල ඇඳුම, ඉණ පටිය සහ ජටාව", "රකුසු වෙස්මුහුණ", "කෝලම් ඇඳුම", "පාවහන් සහිත කබාය", "උත්සව අවස්ථාවලදී චාම් හා ගෞරවනීය පිරිසිදු ඇඳුමකින් බෙරකරුවන් සැරසේ."),
        q("උඩරට 'ගැටබෙර' වාදනයේදී 'මුල් සුළු හුරුව' යනුවෙන් හඳුන්වන්නේ කුමක්ද?", "ආධුනිකයන් පුහුණු වන මූලික අත් පද සහ බීජාක්ෂර වාදනය", "වෙස් තට්ටු පැළඳීම", "වන්නම් කවි ලිවීම", "බෙර සම් ගැලවීම", "තත්, ජිත්, තොං, නං යන ශුද්ධ අක්ෂර මූලිකව පුහුණු කෙරේ."),
        q("සබරගමු 'දිගු දවුලේ' ඇස් දෙක ආවරණය කිරීමේදී වරපටිවලින් තද කරන්නේ කුමන වළල්ල හරහාද?", "වෙණිවැල් හෝ වේවැල් වළල්ල (කුරලය)", "පිත්තල තැටිය", "රබර් වළල්ල", "ලෝහ දම්වැල", "වළල්ල වටා වරපටි ඇද ගැට ගැසීමෙන් හම තද කර ගනී."),
        q("'නාග සින්නම්' හෝ 'හොරණෑව' වැනි සුසිර වාද්‍ය භාණ්ඩ දේවාලවල වැඩි වශයෙන්ම වයන්නේ ඇයි?", "මිහිරි නාදය ඈතට විහිදී පූජනීය වාතාවරණයක් මැවෙන බැවින්", "බෙර හඬ නතර කිරීමට", "නැට්ටුවන් බිය ගැන්වීමට", "තාලම්පට වෙනුවට", "හේවිසි නාදයට තනුව හා මාධූර්යය ගෙන එන්නේ හොරණෑවයි."),
        q("දේශීය නර්තන වාද්‍ය භාණ්ඩ අතර 'බෙර පද' ලියා තබා ගැනීමේදී භාවිත කරන ක්‍රමය කුමක්ද?", "තාල ලිපි හෙවත් මාත්‍රා අනුව බෙර අක්ෂර සටහන් කිරීම", "වෙස්මුහුණු රූප චිත්‍ර ලෙස ඇඳීම පමණක්", "මාත්‍රා හෝ තාල නැතිව කවි පද ගොඩගැසීම", "රාග හා බටහිර ස්වර ප්‍රස්තාර පමණක් ලිවීම", "තාල ශාස්ත්‍රය අනුව විභාග බෙදා බෙර පද පොත්වල ලේඛනගත කෙරේ."),
        q("පහතරට 'යක් බෙරය' සෑදීමට බහුලව ගන්නා 'ඇහැල' හෝ 'කොස්' ලීයෙහි ඇති විශේෂත්වය කුමක්ද?", "සවිමත් බව, කල් පැවැත්ම සහ හොඳ නාද අනුනාදය", "ඉතා මෘදු වී ඉක්මනින් දිරා යාම", "ජලයේ දිය වීම", "කෘමීන්ට පහසුවෙන් කෑමට හැකි වීම", "දැව තෝරා ගැනීම බෙරයක ගුණාත්මක බවට සෘජුව බලපායි."),
        q("උඩරට නැටුමේදී 'තාලම්පට' වයන්නා නැට්ටුවන් ඉදිරියේ හෝ පසෙකින් සිට කරන කාර්යය කුමක්ද?", "කවි හා පදවල තාල ලය අඛණ්ඩව රැක දීම", "බෙර වාදනය නතර කිරීම", "වෙස් තට්ටු පැළඳීම", "වේදිකාවෙන් පිටව යාම", "නැටුමේ පාලකයා ලෙස තාලම්පට වාදකයා ක්‍රියා කරයි."),
        q("'ඩමරුව' නමැති කුඩා වාද්‍ය භාණ්ඩය හා සම්බන්ධ පෙරදිග දෙවියන් කවුද?", "නටරාජ හෙවත් ශිව දෙවියන්", "ඉන්ද්‍ර දෙවියන්", "වරුණ දෙවියන්", "අග්නි දෙවියන්", "ශිව දෙවියන්ගේ තාණ්ඩව නර්තනයේදී අත දරන භාණ්ඩය ඩමරුවයි."),
        q("නර්තන වාද්‍ය භාණ්ඩ අතර 'කයිතාලම' වැඩි වශයෙන්ම දක්නට ලැබෙන්නේ කුමන නර්තන හා පූජා ආශ්‍රිතවද?", "භරත නාට්‍යම්, නාඩගම් සහ හින්දු කෝවිල් පූජාවන්හි", "කළගෙඩි නැටුමේදී පමණක්", "ගොයම් නැටුමේදී පමණක්", "ලී කෙළි නැටුමේදී පමණක්", "භාරතීය කර්ණාටක සංගීතයේ හා කෝවිල් පූජාවල තාල උපකරණය මෙයයි."),
        q("ශ්‍රී ලංකාවේ 'ගැමි රබාන' (බංකු රබාන) තබා ගැනීමට ගන්නා ආධාරකය කුමක්ද?", "රබානේ පතුල යටින් තබන ලී බංකුව හෝ කණු තුන", "ලෝහ දම්වැලකින් එල්ලා තබන ඉහළ ආධාරකය", "වීදුරු තහඩුවක් මත තබන පැතලි මේසය", "හිස් මැටි කළයක් මත සවි කරන රාමුව", "බිමට ඉහළින් රබාන රඳවා වාදනය කිරීමෙන් පැහැදිලි ශබ්දයක් ලැබේ."),
        q("වාද්‍ය භාණ්ඩයක් වන 'හොරණෑවේ' පිත්තල කෝණය නොමැති නම් සිදු වන්නේ කුමක්ද?", "ශබ්දය දුරට විහිදී යාම හා නාද ඝනත්වය අඩු වීම", "තල්පත් පීප්පය වේගයෙන් කැඩී ඉරී යාම", "අසල ඇති බෙර සම් ඉබේම බුරුල් වී යාම", "නැටුමේ තාලය දෙගුණයකින් වේගවත් වීම", "කෝණාකාර පිත්තල කොටස ශබ්ද වර්ධකයක් ලෙස ක්‍රියා කරයි."),
        q("'පන්තේරුව' වාදනය කරන නැට්ටුවා තාල නාද උපදවන්නේ කුමන ශාරීරික ක්‍රියාවකින්ද?", "වළල්ල කරකවමින් අල්ලෙන් හා උරහිසෙන් තට්ටු කිරීම", "මුවින් සුළං පිඹිමින් ලෝහ පෙති සෙලවීමෙන්", "කඩිප්පු දෙකකින් වළල්ල මැදට ගැසීමෙන්", "පාදයෙන් වළල්ල බිමට තද කොට පෑගීමෙන්", "පන්තේරුව ඇඟේ විවිධ කොටස්වල වද්දා තාල නාද මැවීම විශේෂ ශිල්පයකි."),
        q("දේශීය බෙර වාදනයේදී 'වම් අත' සහ 'දකුණු අත' මාරු කර වැයීමෙන් වාදකයා ලබන ප්‍රධාන ප්‍රතිඵලය කුමක්ද?", "ශබ්ද වර්ණ විවිධත්වය සහ වේගවත් පද වැයීම", "බෙර සම් හා කුරලය ඉක්මනින් කැඩී යාම", "වාදනය කරන තාලය හා ලය අමතක වී යාම", "බෙරයේ ස්වාභාවික අනුනාද ශබ්දය නැති වීම", "අක්ෂර නිරවද්‍යතාව හා නාද ලාලිත්‍යය දෙඅත් හුරුවෙන් ලැබේ."),
        q("පංචතූර්ය වර්ගීකරණයේදී 'තත් වාද්‍ය භාණ්ඩ' (සිතාරය, වීණාව) නූතනයේ හඳුන්වන නම කුමක්ද?", "තත වාද්‍ය භාණ්ඩ (Chordophones)", "සුසිර වාද්‍ය භාණ්ඩ", "ඝන වාද්‍ය භාණ්ඩ", "අවනද්ධ වාද්‍ය භාණ්ඩ", "ඇද ගැසූ තන්තු කම්පනය වීමෙන් ස්වර උපදවන භාණ්ඩ මීට අයත් වේ."),
        q("උඩරට නැටුමේදී 'ගැටබෙර' වාදකයාට ප්‍රසංග වේදිකාවේ හිමි වන ස්ථානය කුමක්ද?", "නැට්ටුවන්ට අත්වැල් සපයමින් වේදිකාවේ පැත්තකින් හෝ පසුපසින් ගෞරවනීය ලෙස සිටීම", "වේදිකාවෙන් සම්පූර්ණයෙන් පිටත අඳුරු කුටියක සැඟවී සිට බෙර වැයීම", "ප්‍රේක්ෂක නරඹන්නන් අතර පසුපස පෙළේ අසුන් ගෙන සිට බෙර වාදනය කිරීම", "නැට්ටුවන්ගේ පාද චලනවලට බාධා කරමින් වේදිකාව හරි මැද බිම හිඳගැනීම", "වාදකයා සහ නැට්ටුවා අතර මුහුණට මුහුණ සම්බන්ධතාව වේදිකාවේදී ඉතා වැදගත් වේ."),
        q("ශ්‍රී ලාංකේය බෙර වර්ග අතර 'තම්මැට්ටමේ' හඬ ඉතා ඈතට ඇසෙන්නේ කුමන හේතුවක් නිසාද?", "ශක්තිමත් කඩිප්පු යුගලයෙන් තදින් පහර දී වාදනය කරන බැවින්", "එය මුවින් පිඹින බැවින්", "එය තුළ විදුලි ස්පීකර ඇති බැවින්", "එය පිත්තලවලින් සාදා ඇති බැවින්", "එළිමහන් පෙරහැර හා හේවිසි සඳහා තම්මැට්ටම අතිශයින් උචිත වේ."),
        q("O/L නර්තන විෂය හදාරන සිසුවෙකුට 'පංචතූර්ය නාද වර්ගීකරණය' ඉගෙනීමෙන් ලැබෙන ප්‍රධාන දැනුම කුමක්ද?", "ඕනෑම වාද්‍ය භාණ්ඩයක් එහි ශබ්ද උපදවන ක්‍රමය අනුව විද්‍යාත්මකව වර්ග කිරීම", "බෙර කඳන් කපා ලී කැටයම් හා වෙස්මුහුණු අලංකාර කිරීම පමණක් ඉගෙනීම", "බටහිර පොප් හා ජෑස් ගීත තනු පමණක් කටපාඩම් කර ගැනීමට හුරු වීම", "වේදිකා පසුබිම් චිත්‍ර හා තිර රෙදි ඇඳීම පමණක් ප්‍රගුණ කිරීම", "දේශීය හා පෙරදිග සංගීත උපකරණ පිළිබඳ ශාස්ත්‍රීය අවබෝධය මින් වර්ධනය වේ.")
    )
}
